// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";
import {CoolerFactory} from "../src/Cooler.sol";
import {ERC20} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    CoolerFactory factory;

    function setUp() public {
        factory = new CoolerFactory();
    }

    function testFuzz_property(address owner, address collateralToken, address debtToken) public {
        vm.assume(owner != address(0));
        vm.assume(collateralToken != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(owner != debtToken);

        vm.prank(owner);
        c = Cooler(factory.generateCooler(ERC20(collateralToken), ERC20(debtToken)));

        assertTrue(c.owner() == owner);
    }
}
